import 'package:test/test.dart';

const _settings = CompactionSettings(
  enabled: true,
  reserveTokens: 200,
  keepRecentTokens: 200,
);

Model get _model => const Model(
  id: 'm1',
  api: 'test-api',
  provider: 'p',
  baseUrl: 'http://localhost:1',
  contextWindow: 8000,
  maxTokens: 4096,
);

AssistantMessage _assistant(
  String text, {
  Usage? usage,
}) => AssistantMessage(
  content: [TextContent(text: text)],
  api: 'test-api',
  provider: 'p',
  model: 'm1',
  usage: usage ?? Usage.zero,
  stopReason: StopReason.stop,
  timestamp: DateTime.utc(2026),
);

ToolResultMessage _result(String callId, String text) => ToolResultMessage(
  toolCallId: callId,
  toolName: 'read',
  content: [TextContent(text: text)],
  isError: false,
  timestamp: DateTime.utc(2026),
);

/// Usage reporting 5000 context tokens — the anchor the gate sees.
Usage get _anchoredUsage => const Usage(
  input: 4000,
  output: 500,
  cacheRead: 500,
  cacheWrite: 0,
  totalTokens: 5000,
  cost: UsageCost(),
);

