// gh-2237 — CLI-level integration tests for the compaction receipt
// contract:
//
// IT-2: a receipt-free zero-pass funnel is impossible — a
//   message-cap-armed post-run attempt on a transcript under the token
//   trigger prints `auto-compact done passes=0 (no-op: basis N below
//   trigger M at the run gate)` on the diagnostic lane AND a dim
//   user-facing row, and makes ZERO compaction-lane provider calls
//   (observable, not silent).
// IT-5/IT-1: an anchored over-trigger transcript still folds ≥1 pass —
//   the lab cascade shape. The pre-fix engine collapsed the anchored
//   basis to chars/4, exited under-trigger with zero passes, and
//   re-fired the gate every turn (the field S1 loop).
// REG-2/IT-3: forced `/compact` on an under-trigger transcript still
//   prints a visible fold (classic fall-through intact — the probe
//   parity the lab proved is by code, not transcript shape).

library;

import 'dart:convert';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/compaction/receipt_scan.dart';
import 'package:test/test.dart';

import 'agent_cli_test_support.dart';

const _provider = 'test-provider';

Model get _model => const Model(
  id: 'test-model',
  api: 'test-api',
  provider: _provider,
  baseUrl: 'https://example.test',
  contextWindow: 100000,
  maxTokens: 4096,
);

/// The compaction-lane fake: judge calls (the context-hygiene judge
/// prompt) answer `[]` (hide nothing), checkpoint calls (the "Write a
/// checkpoint" payload) answer a canned summary, real turns answer from
/// [turnAnswers] — optionally carrying a scripted usage anchor.
final class _RecordingCompactionStream {
  final turnAnswers = <String>[];
  final contexts = <Context>[];
  int judgeCalls = 0;
  int checkpointCalls = 0;
  Usage? nextTurnUsage;
  var _answered = 0;

  AssistantMessageEventStream call(
    Model model,
    Context context, {
    CancelToken? cancelToken,
  }) {
    contexts.add(context);
    final system = context.systemPrompt ?? '';
    final prompt = [
      for (final m in context.messages)
        switch (m) {
          UserMessage() => messageText(m),
          AssistantMessage() =>
            m.content.whereType<TextContent>().map((b) => b.text).join(),
          _ => '',
        },
    ].join('\n');
    final String reply;
    if (system.contains('context-hygiene judge')) {
      judgeCalls++;
      reply = '[]';
    } else if (prompt.contains('Write a checkpoint')) {
      checkpointCalls++;
      reply = 'CHECKPOINT: the probe task summary.';
    } else {
      reply = turnAnswers[_answered++ % turnAnswers.length];
    }
    final full = AssistantMessage(
      content: [TextContent(text: reply)],
      api: model.api,
      provider: model.provider,
      model: model.id,
      usage: nextTurnUsage ?? Usage.zero,
      stopReason: StopReason.stop,
      timestamp: DateTime.utc(2026),
    );
    final stream = AssistantMessageEventStream();
    stream
      ..push(StartEvent(partial: AssistantMessage(content: const [])))
      ..push(DoneEvent(reason: StopReason.stop, message: full))
      ..end();
    return stream;
  }
}

AgentCli _cli(
  MemoryExecutionEnv env,
  FakeCliIO io,
  _RecordingCompactionStream stream, {
  int contextWindow = 100000,
  CompactionSettings? compactionSettings,
  Map<String, String> environment = const {},
}) => AgentCli(
  config: AgentCliConfig(
    model: Model(
      id: 'test-model',
      api: 'test-api',
      provider: _provider,
      baseUrl: 'https://example.test',
      contextWindow: contextWindow,
      maxTokens: 4096,
    ),
    apiKey: '[REDACTED:Sensitive-Value]',
    env: env,
    sessionRoot: '/sessions',
    sessionName: 'zero-pass-receipt-target',
    homeDir: '/home',
    providerKind: 'openai-completions',
    skillsAccess: SkillsAccess.granted,
    compactionSettings: compactionSettings,
  ),
  io: io,
  environment: environment,
  streamFunction: stream.call,
);

Future<MemoryExecutionEnv> _seed(List<int> Function() fillerShape) async {
  final env = MemoryExecutionEnv(cwd: '/work', shell: FakeShell());
  // Suppress session-start memory maintenance (suite pattern).
  await env.writeFile('/work/.fah/memory/.last_maintenance', '');
  final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
  final seed = await repo.create(
    JsonlSessionCreateOptions(cwd: '/work', metadata: {'agent': 'cli'}),
  );
  await seed.appendSessionName('zero-pass-receipt-target');
  await seed.appendMessage(UserMessage.text('TASK probe ${'t ' * 100}'));
  for (var i = 0; i < 40; i++) {
    await seed.appendMessage(UserMessage.text('filler$i ${'x' * 100}'));
  }
  return env;
}

/// [waitUntil] with a LAZY description: names the state actually reached.
Future<void> waitUntil(
  bool Function() condition,
  String Function() describe,
) async {
  for (var i = 0; i < 5000; i++) {
    if (condition()) return;
    await Future<void>.delayed(const Duration(milliseconds: 5));
  }
  fail('timed out waiting: ${describe()}');
}

Future<String> _readLog(MemoryExecutionEnv env) async {
  final log = (await env.readTextFile('/home/.fah/logs/fa.log')).valueOrNull;
  expect(log, isNotNull, reason: 'the diagnostic log must exist');
  return log!;
}

void main() {
  test(
    'IT-2: cap-armed zero-pass funnel prints the terminal receipt on '
    'both surfaces and makes zero compaction-lane calls',
    timeout: const Timeout(Duration(minutes: 5)),
    () async {
      final io = FakeCliIO();
      final env = await _seed(() => const []);
      // A learned numeric cap below the live message count: the gh-1680
      // cap gate arms the funnel while the token basis (~2.5k chars/4
      // tokens) sits far under the token trigger — the E4 shape, and
      // post-AC1 the ONLY reachable zero-pass arming.
      await env.writeFile(
        '/home/.fah/model_caps.json',
        jsonEncode({
          ModelCapsStore.keyOf(_provider, 'test-model'): {
            'maxMessages': 20,
          },
        }),
      );
      final stream = _RecordingCompactionStream()..turnAnswers.add('ok');
      final agent = _cli(
        env,
        io,
        stream,
        contextWindow: 100000,
        // Trigger 99900 — far above the basis: the token gate never fires.
        compactionSettings: const CompactionSettings(
          enabled: true,
          reserveTokens: 100,
          keepRecentTokens: 50,
        ),
      );
      final run = agent.run();
      io.sendLine('go');
      await waitUntil(
        () =>
            stream.contexts.isNotEmpty &&
            stream.contexts.any(
              (c) => (c.systemPrompt ?? '').startsWith('You are Fa'),
            ) &&
            !agent.isBusy,
        () => 'turn: calls=${stream.contexts.length} busy=${agent.isBusy}',
      );
      io.sendLine('/exit');
      await run;

      final log = await _readLog(env);
      final compactLines = log
          .split('\n')
          .where((line) => line.contains('auto-compact'))
          .toList();
      expect(
        compactLines.where((line) => line.contains('auto-compact start')),
        isNotEmpty,
        reason: 'the fixture must arm the funnel (cap gate)',
      );
      final terminalReceipts = compactLines
          .where(
            (line) =>
                line.contains('auto-compact done') &&
                line.contains('passes=0'),
          )
          .toList();
      expect(
        terminalReceipts,
        isNotEmpty,
        reason:
            'AC2: a started compaction can never end in silence — the '
            'zero-pass outcome must print its terminal receipt',
      );
      for (final line in terminalReceipts) {
        expect(line, contains('no-op: basis '));
        expect(line, contains(' below trigger '));
        expect(line, contains('at the run gate)'));
      }
      // PF5 kept: the engine exited BEFORE the first judge call — now
      // observable and asserted, not silent.
      expect(stream.judgeCalls, 0);
      expect(stream.checkpointCalls, 0);
      // REG-1: no start-without-terminal-receipt signature anywhere.
      expect(
        compactionStartWithoutTerminalReceipt(log.split('\n')),
        isFalse,
      );
      // OQ2: the dim user-facing row (boot-cap defer precedent).
      expect(
        io.out.toString(),
        contains('no-op'),
        reason: 'the zero-pass receipt must render as a dim user row too',
      );
    },
  );

  test(
    'IT-5: anchored over-trigger transcript folds ≥1 pass (no collapse)',
    timeout: const Timeout(Duration(minutes: 5)),
    () async {
      final io = FakeCliIO();
      final env = await _seed(() => const []);
      // Anchor the transcript at 55k tokens (the lab's scripted-usage
      // shape): the anchored basis sits over the 45k trigger while the
      // chars/4 projection (~2.5k) sits far under it — the exact
      // divergence that used to zero-pass the engine.
      final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
      final sessions = await repo.list();
      final target = sessions.firstWhere(
        (s) => s.name == 'zero-pass-receipt-target',
      );
      final session = await repo.open(target.id);
      await session.appendMessage(
        AssistantMessage(
          content: [const TextContent(text: 'anchor turn')],
          api: 'test-api',
          provider: _provider,
          model: 'test-model',
          usage: const Usage(
            input: 50000,
            output: 5000,
            cacheRead: 0,
            cacheWrite: 0,
            totalTokens: 55000,
            cost: UsageCost(),
          ),
          stopReason: StopReason.stop,
          timestamp: DateTime.utc(2026),
